script.setup:
// Meyda extracts audio features from the playing loop: chroma (12 pitch classes,
// around the circle of fifths), loudness (RMS, the core) and spectral centroid (its color).
const mod = await ctx.utils.import("https://esm.sh/meyda@5.6.3?bundle");
const Meyda = mod.default ?? mod;
const audio = new AudioContext();
const element = new Audio(ctx.assets["beat.wav"]);
element.loop = true;
const source = audio.createMediaElementSource(element);
source.connect(audio.destination);
const features = { chroma: new Array(12).fill(0), rms: 0, spectralCentroid: 0 };
const analyzer = Meyda.createMeydaAnalyzer({
  audioContext: audio, source, bufferSize: 1024,
  featureExtractors: ["chroma", "rms", "spectralCentroid"],
  callback: (f) => Object.assign(features, f),
});
analyzer.start();
const resume = () => { audio.resume(); element.play().catch(() => {}); };
resume();
window.addEventListener("pointerdown", resume);
const FIFTHS = [0, 7, 2, 9, 4, 11, 6, 1, 8, 3, 10, 5];
Object.assign(ctx.state, { audio, element, analyzer, features, resume, FIFTHS, chroma: new Float32Array(12), rms: 0, centroid: 0,
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor;\nuniform vec2 u_resolution; uniform float u_chroma[12]; uniform float u_rms; uniform float u_centroid;\nvec3 hue(float h){ return clamp(abs(fract(h + vec3(0.0, 2.0/3.0, 1.0/3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0); }\nvoid main(){\n  vec2 p = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);\n  float r = length(p), a = fract(atan(p.x, p.y) / 6.2831853);\n  int k = int(a * 12.0);\n  float c = pow(u_chroma[k], 2.5);\n  float wedge = smoothstep(0.5, 0.42, abs(fract(a * 12.0) - 0.5));\n  float band = step(0.2, r) * step(r, 0.2 + 0.24 * max(c, 0.15)) * wedge;\n  vec3 col = hue(float(k) / 12.0) * band * (0.5 + 0.5 * c);\n  float core = smoothstep(0.06 + u_rms * 0.45, 0.0, r);\n  col += mix(vec3(1.0, 0.5, 0.2), vec3(0.4, 0.7, 1.0), u_centroid) * core;\n  outColor = vec4(col + vec3(0.02, 0.02, 0.03), 1.0);\n}") });

script.render:
const s = ctx.state, f = s.features, k = 1 - Math.exp(-ctx.dt * 12);
// Silence (audio not started yet) gives NaN chroma and centroid (0 / 0); treat it as 0.
const num = (v) => (Number.isFinite(v) ? v : 0);
s.FIFTHS.forEach((pitch, i) => { s.chroma[i] += (num(f.chroma?.[pitch]) - s.chroma[i]) * k; });
s.rms += (num(f.rms) * 2.5 - s.rms) * k;
s.centroid += (Math.min(1, num(f.spectralCentroid) / 160) - s.centroid) * k;
ctx.publish("rms", Number(s.rms.toFixed(3)));
// Browsers may hold audio until a gesture.
ctx.publish("audio", s.audio.state === "running" && !s.element.paused ? "playing" : "click the viewport to start");
ctx.gl.useProgram(s.p);
ctx.utils.drawFullscreen(s.p, { u_chroma: s.chroma, u_rms: Math.min(1, s.rms), u_centroid: s.centroid });

script.cleanup:
const s = ctx.state;
window.removeEventListener("pointerdown", s.resume);
s.analyzer?.stop(); s.element?.pause(); s.audio?.close();
